<?php

// phpcs:ignoreFile

/**
 * @file
 * Site settings. Contains no secrets: credentials come from the environment.
 *
 * - DDEV: settings.ddev.php (generated by `ddev start`) provides the database
 *   connection and hash salt.
 * - Elsewhere: set DRUPAL_DB_* and DRUPAL_HASH_SALT, or add settings.local.php
 *   (see example.settings.local.php; settings.local.php is gitignored).
 */

$databases = [];

if (getenv('DRUPAL_DB_NAME')) {
  $databases['default']['default'] = [
    'driver' => getenv('DRUPAL_DB_DRIVER') ?: 'mysql',
    'database' => getenv('DRUPAL_DB_NAME'),
    'username' => getenv('DRUPAL_DB_USER'),
    'password' => getenv('DRUPAL_DB_PASSWORD'),
    'host' => getenv('DRUPAL_DB_HOST') ?: 'localhost',
    'port' => getenv('DRUPAL_DB_PORT') ?: '3306',
    'prefix' => '',
  ];
}

$settings['hash_salt'] = getenv('DRUPAL_HASH_SALT') ?: '';
$settings['config_sync_directory'] = '../config/sync';
$settings['file_scan_ignore_directories'] = ['node_modules', 'bower_components'];
$settings['entity_update_batch_size'] = 50;
$settings['entity_update_backup'] = TRUE;
$settings['update_free_access'] = FALSE;

if ($trusted = getenv('DRUPAL_TRUSTED_HOSTS')) {
  $settings['trusted_host_patterns'] = explode(',', $trusted);
}

// Payment gateway credentials are kept out of exported config.
if (getenv('LIQPAY_PUBLIC_KEY')) {
  $config['commerce_payment.commerce_payment_gateway.liqpay']['status'] = TRUE;
  $config['commerce_payment.commerce_payment_gateway.liqpay']['configuration']['public_key'] = getenv('LIQPAY_PUBLIC_KEY');
  $config['commerce_payment.commerce_payment_gateway.liqpay']['configuration']['private_key'] = getenv('LIQPAY_PRIVATE_KEY');
}
if (getenv('NOVAPOSHTA_API_KEY')) {
  $config['commerce_novaposhta.novaposhta']['api_key'] = getenv('NOVAPOSHTA_API_KEY');
}

if (getenv('IS_DDEV_PROJECT') == 'true') {
  if (file_exists(__DIR__ . '/settings.ddev.php')) {
    include __DIR__ . '/settings.ddev.php';
  }
  $settings['config_sync_directory'] = '../config/sync';

  // Solr runs as the ddev-solr add-on (Solr Cloud with basic auth).
  $solr = &$config['search_api.server.products']['backend_config'];
  $solr['connector'] = 'solr_cloud_basic_auth';
  $solr['connector_config']['host'] = 'solr';
  $solr['connector_config']['context'] = 'solr';
  $solr['connector_config']['username'] = 'solr';
  $solr['connector_config']['password'] = 'SolrRocks';
  unset($solr);
}

if (file_exists(__DIR__ . '/settings.local.php')) {
  include __DIR__ . '/settings.local.php';
}
